True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * (w // 3) for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            vals = [grid[r][c] for r in range(br * 3, br * 3 + 3)
